// Receipt run-log report tool. Node.js builtins only.

import { readFileSync, realpathSync, writeSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import process from 'node:process';

const TYPES = new Set(['started', 'succeeded', 'failed']);

function fail(message) {
  writeSync(2, `${message}\n`);
  process.exit(2);
}

function validateEvent(value, lineNumber) {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    throw new TypeError(`line ${lineNumber}: event must be a JSON object`);
  }
  const { id, job, attempt, seq, type } = value;
  if (typeof id !== 'string' || id.length === 0) {
    throw new TypeError(`line ${lineNumber}: id must be a nonempty string`);
  }
  if (typeof job !== 'string' || job.length === 0) {
    throw new TypeError(`line ${lineNumber}: job must be a nonempty string`);
  }
  if (!Number.isSafeInteger(attempt) || attempt < 1) {
    throw new TypeError(`line ${lineNumber}: attempt must be a positive safe integer`);
  }
  if (!Number.isSafeInteger(seq) || seq < 0) {
    throw new TypeError(`line ${lineNumber}: seq must be a nonnegative safe integer`);
  }
  if (typeof type !== 'string' || !TYPES.has(type)) {
    throw new TypeError(`line ${lineNumber}: type must be started, succeeded, or failed`);
  }
  return { id, job, attempt, seq, type };
}

export function reduceEvents(text) {
  if (typeof text !== 'string') {
    if (text instanceof Uint8Array) {
      text = Buffer.from(text).toString('utf8');
    } else {
      throw new TypeError('input must be a UTF-8 JSONL string');
    }
  }
  if (text.charCodeAt(0) === 0xfeff) {
    text = text.slice(1);
  }

  const seen = new Map();
  const events = [];
  let duplicates = 0;

  const lines = text.split(/\r\n|\n/);
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (line === '') continue;
    let value;
    try {
      value = JSON.parse(line);
    } catch (err) {
      throw new SyntaxError(`line ${i + 1}: invalid JSON (${err.message})`);
    }
    const event = validateEvent(value, i + 1);
    const previous = seen.get(event.id);
    if (previous === undefined) {
      seen.set(event.id, event);
      events.push(event);
    } else if (
      previous.job === event.job &&
      previous.attempt === event.attempt &&
      previous.seq === event.seq &&
      previous.type === event.type
    ) {
      duplicates += 1;
    } else {
      throw new Error(
        `line ${i + 1}: id ${JSON.stringify(event.id)} conflicts with an earlier event`,
      );
    }
  }

  const jobMap = new Map();
  for (const event of events) {
    let attempts = jobMap.get(event.job);
    if (attempts === undefined) {
      attempts = new Map();
      jobMap.set(event.job, attempts);
    }
    let group = attempts.get(event.attempt);
    if (group === undefined) {
      group = { start: null, terminal: null };
      attempts.set(event.attempt, group);
    }
    if (event.type === 'started') {
      if (group.start !== null) {
        throw new Error(
          `job ${JSON.stringify(event.job)} attempt ${event.attempt}: repeated start`,
        );
      }
      group.start = event;
    } else if (group.terminal !== null) {
      throw new Error(
        `job ${JSON.stringify(event.job)} attempt ${event.attempt}: repeated or contradictory terminal`,
      );
    } else {
      group.terminal = event;
    }
  }

  const jobs = [];
  for (const [job, attempts] of jobMap) {
    const reduced = [];
    for (const [attempt, group] of attempts) {
      if (group.start === null) {
        throw new Error(
          `job ${JSON.stringify(job)} attempt ${attempt}: terminal without a started event`,
        );
      }
      const { start, terminal } = group;
      if (terminal !== null && terminal.seq <= start.seq) {
        throw new Error(
          `job ${JSON.stringify(job)} attempt ${attempt}: terminal seq must be greater than start seq`,
        );
      }
      reduced.push({
        attempt,
        status: terminal === null ? 'running' : terminal.type,
        startedSeq: start.seq,
        finishedSeq: terminal === null ? null : terminal.seq,
      });
    }
    reduced.sort((a, b) => a.attempt - b.attempt);
    jobs.push({ job, attempts: reduced });
  }
  jobs.sort((a, b) => (a.job < b.job ? -1 : a.job > b.job ? 1 : 0));
  return { jobs, duplicates };
}

function runCli() {
  const args = process.argv.slice(2);
  if (args.length !== 1) {
    fail('usage: node receipt-report.js LOGFILE');
  }
  const file = args[0];
  let text;
  try {
    text = readFileSync(file, 'utf8');
  } catch (err) {
    fail(`cannot read ${JSON.stringify(file)}: ${err.code ?? err.message}`);
  }
  let report;
  try {
    report = reduceEvents(text);
  } catch (err) {
    fail(err instanceof Error ? err.message : String(err));
  }
  writeSync(1, `${JSON.stringify(report)}\n`);
}

let isMain = false;
const entry = process.argv[1];
if (typeof entry === 'string' && entry.length > 0) {
  try {
    isMain = pathToFileURL(realpathSync(entry)).href === import.meta.url;
  } catch {
    isMain = false;
  }
}
if (isMain) {
  runCli();
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { reduceEvents } from '../receipt-report.js';

const jsonl = events => events.map(event => JSON.stringify(event)).join('\n');
const start = (id, job, attempt, seq) => ({ id, job, attempt, seq, type: 'started' });
const done = (id, job, attempt, seq, type = 'succeeded') => ({ id, job, attempt, seq, type });

test('empty input variants', () => {
  assert.deepEqual(reduceEvents(''), { jobs: [], duplicates: 0 });
  assert.deepEqual(reduceEvents('\n\n'), { jobs: [], duplicates: 0 });
  assert.deepEqual(reduceEvents('\r\n   \r\n'), { jobs: [], duplicates: 0 });
});

test('CRLF endings and missing final newline', () => {
  const text =
    JSON.stringify(start('a', 'j', 1, 1)) +
    '\r\n' +
    JSON.stringify(done('b', 'j', 1, 2));
  assert.deepEqual(reduceEvents(text), {
    jobs: [
      {
        job: 'j',
        attempts: [{ attempt: 1, status: 'succeeded', startedSeq: 1, finishedSeq: 2 }],
      },
    ],
    duplicates: 0,
  });
});

test('every extra duplicate copy is counted, extra fields ignored', () => {
  const e = start('a', 'j', 1, 0);
  const report = reduceEvents(jsonl([e, { ...e }, { ...e, meta: 1 }, { ...e, other: 'x' }]));
  assert.equal(report.duplicates, 3);
  assert.equal(report.jobs[0].attempts.length, 1);
});

test('conflicting duplicate id throws', () => {
  assert.throws(() => reduceEvents(jsonl([start('a', 'j', 1, 0), start('a', 'j', 1, 1)])));
  assert.throws(() => reduceEvents(jsonl([start('a', 'j', 1, 0), done('a', 'j', 1, 2)])));
  assert.throws(() => reduceEvents(jsonl([start('a', 'j', 1, 0), start('a', 'k', 1, 0)])));
  assert.throws(() => reduceEvents(jsonl([start('a', 'j', 1, 0), start('a', 'j', 2, 0)])));
});

test('invalid required fields throw without coercion', () => {
  const base = start('a', 'j', 1, 0);
  const bads = [
    { ...base, id: '' },
    { ...base, id: 5 },
    { ...base, id: null },
    { ...base, job: '' },
    { ...base, job: false },
    { ...base, attempt: 0 },
    { ...base, attempt: -1 },
    { ...base, attempt: 1.5 },
    { ...base, attempt: '1' },
    { ...base, attempt: Number.MAX_SAFE_INTEGER + 1 },
    { ...base, seq: -1 },
    { ...base, seq: 1.5 },
    { ...base, seq: '0' },
    { ...base, seq: Number.MAX_SAFE_INTEGER + 1 },
    { ...base, type: 'Started' },
    { ...base, type: 'done' },
    { ...base, type: 1 },
  ];
  for (const field of ['id', 'job', 'attempt', 'seq', 'type']) {
    const copy = { ...base };
    delete copy[field];
    bads.push(copy);
  }
  for (const bad of bads) {
    assert.throws(
      () => reduceEvents(JSON.stringify(bad)),
      undefined,
      `expected throw for ${JSON.stringify(bad)}`,
    );
  }
});

test('non-object lines throw', () => {
  for (const line of ['null', '[1]', '"x"', '42', 'true', '{bad', '']) {
    if (line === '') continue;
    assert.throws(() => reduceEvents(line), undefined, `line: ${line}`);
  }
  assert.throws(() => reduceEvents('{bad'));
});

test('orphan terminal throws', () => {
  assert.throws(() => reduceEvents(jsonl([done('a', 'j', 1, 5)])));
  assert.throws(
    () =>
      reduceEvents(
        jsonl([start('a', 'j', 1, 0), done('b', 'j', 1, 2), done('c', 'k', 1, 3)]),
      ),
  );
});

test('repeated starts with different ids throw', () => {
  assert.throws(() => reduceEvents(jsonl([start('a', 'j', 1, 0), start('b', 'j', 1, 3)])));
});

test('repeated or contradictory terminals throw', () => {
  assert.throws(
    () =>
      reduceEvents(
        jsonl([
          start('a', 'j', 1, 0),
          done('b', 'j', 1, 2, 'succeeded'),
          done('c', 'j', 1, 3, 'failed'),
        ]),
      ),
  );
  assert.throws(
    () =>
      reduceEvents(
        jsonl([start('a', 'j', 1, 0), done('b', 'j', 1, 2), done('c', 'j', 1, 4)]),
      ),
  );
});

test('terminal seq must be strictly greater than start seq', () => {
  assert.throws(() => reduceEvents(jsonl([start('a', 'j', 1, 5), done('b', 'j', 1, 5)])));
  assert.throws(() => reduceEvents(jsonl([start('a', 'j', 1, 5), done('b', 'j', 1, 4)])));
});

test('jobs sorted by UTF-16 order, attempts numerically, gaps and overlaps allowed', () => {
  const report = reduceEvents(
    jsonl([
      start('c', 'banana', 1, 0),
      start('d', 'Apple', 3, 0),
      start('e', 'Apple', 10, 5),
      done('f', 'Apple', 3, 7, 'failed'),
      start('g', 'Apple', 1, 5),
      done('h', 'Apple', 1, 6),
    ]),
  );
  assert.deepEqual(report, {
    jobs: [
      {
        job: 'Apple',
        attempts: [
          { attempt: 1, status: 'succeeded', startedSeq: 5, finishedSeq: 6 },
          { attempt: 3, status: 'failed', startedSeq: 0, finishedSeq: 7 },
          { attempt: 10, status: 'running', startedSeq: 5, finishedSeq: null },
        ],
      },
      {
        job: 'banana',
        attempts: [{ attempt: 1, status: 'running', startedSeq: 0, finishedSeq: null }],
      },
    ],
    duplicates: 0,
  });
});

test('ids like __proto__ and odd job strings are ordinary strings', () => {
  const report = reduceEvents(
    jsonl([
      start('__proto__', '  spaced job  ', 1, 0),
      done('__proto__', '  spaced job  ', 1, 9),
      start('toString', 'ünïcode', 2, 0),
    ]),
  );
  assert.equal(report.duplicates, 0);
  assert.deepEqual(report.jobs[0], {
    job: '  spaced job  ',
    attempts: [{ attempt: 1, status: 'succeeded', startedSeq: 0, finishedSeq: 9 }],
  });
  assert.equal(report.jobs[1].job, 'ünïcode');
  assert.equal(report.jobs[1].attempts[0].attempt, 2);
});

test('different attempts are independent and may share seqs', () => {
  const report = reduceEvents(
    jsonl([
      start('a', 'j', 1, 5),
      done('b', 'j', 1, 6),
      start('c', 'j', 2, 5),
      done('d', 'j', 2, 6, 'failed'),
      start('e', 'k', 1, 5),
    ]),
  );
  assert.deepEqual(report.jobs, [
    {
      job: 'j',
      attempts: [
        { attempt: 1, status: 'succeeded', startedSeq: 5, finishedSeq: 6 },
        { attempt: 2, status: 'failed', startedSeq: 5, finishedSeq: 6 },
      ],
    },
    {
      job: 'k',
      attempts: [{ attempt: 1, status: 'running', startedSeq: 5, finishedSeq: null }],
    },
  ]);
});

test('events may arrive in any order', () => {
  const report = reduceEvents(
    jsonl([
      done('b', 'j', 1, 2),
      start('a', 'j', 1, 1),
      start('c', 'j', 2, 0),
    ]),
  );
  assert.deepEqual(report.jobs[0].attempts, [
    { attempt: 1, status: 'succeeded', startedSeq: 1, finishedSeq: 2 },
    { attempt: 2, status: 'running', startedSeq: 0, finishedSeq: null },
  ]);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdirSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const cliPath = join(here, '..', 'receipt-report.js');
const dir = mkdirSync(join(tmpdir(), `receipt-report-${process.pid}-${Date.now()}`), {
  recursive: true,
});

function write(name, content) {
  const file = join(dir, name);
  writeFileSync(file, content, 'utf8');
  return file;
}

function run(...args) {
  return spawnSync(process.execPath, [cliPath, ...args], { encoding: 'utf8' });
}

test('CLI prints the report JSON plus newline and exits 0', () => {
  const file = write(
    'ok.jsonl',
    [
      JSON.stringify({ id: 'a', job: 'j', attempt: 1, seq: 0, type: 'started' }),
      JSON.stringify({ id: 'b', job: 'j', attempt: 1, seq: 3, type: 'succeeded' }),
    ].join('\n'),
  );
  const result = run(file);
  assert.equal(result.status, 0);
  assert.equal(result.stderr, '');
  assert.match(result.stdout, /\n$/);
  assert.deepEqual(JSON.parse(result.stdout), {
    jobs: [
      {
        job: 'j',
        attempts: [{ attempt: 1, status: 'succeeded', startedSeq: 0, finishedSeq: 3 }],
      },
    ],
    duplicates: 0,
  });
});

test('CLI exits 2 with empty stdout for bad input', () => {
  const cases = [
    [],
    ['a', 'b'],
    [join(dir, 'does-not-exist.jsonl')],
    [dir],
    [write('bad-json.jsonl', '{nope')],
    [write('bad-event.jsonl', JSON.stringify({ id: 'a' }) + '\n'),
  ];
  for (const args of cases) {
    const result = run(...args);
    assert.equal(result.status, 2, `args: ${JSON.stringify(args)}`);
    assert.equal(result.stdout, '', `args: ${JSON.stringify(args)}`);
    assert.ok(result.stderr.length > 0, `args: ${JSON.stringify(args)}`);
  }
});

test('importing the module does not run the CLI', () => {
  const moduleUrl = fileURLToPath(new URL('../receipt-report.js', import.meta.url));
  const result = spawnSync(
    process.execPath,
    [
      '-e',
      `import(${JSON.stringify(moduleUrl)}).then(m => console.log(typeof m.reduceEvents))`,
    ],
    { encoding: 'utf8' },
  );
  assert.equal(result.status, 0);
  assert.equal(result.stderr, '');
  assert.equal(result.stdout, 'function\n');
});

